/bin/bash -lc "python - <<'PY'
import os, requests, csv, io, collections
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
headers={'x-api-key':key}
datasets={'gained':'f9cad7b01a472135ee1b1d44febeb1a1','initial_enriched':'f9cad7b01a47213506ff0e9cd140ec1b'}
fam={
'FOXA1':['FOXA1'], 'ASCL1':['ASCL1'], 'TFAP2A':['TFAP2A'], 'RUNX1':['RUNX2','RUNX3'],
'KLF4':['KLF4'], 'PAX7':['PAX3'], 'TCF7':['TCF7','TCF7L1','TCF7L2'], 'REST':['REST'],
'SPI1':['SPIB','SPIC'], 'GATA3':['GATA1','GATA2','GATA4','GATA5','GATA6']
}
for label,dataset in datasets.items():
    text=requests.get(f'{url}/api/datasets/{dataset}/display', headers=headers, timeout=60).text
    rows=[]
    for row in csv.DictReader(io.StringIO(text), delimiter='\\t'):
        if not row.get('motif_id') or row['motif_id'].startswith('#'): continue
        rows.append((row['motif_alt_id'], float(row['p-value']), float(row['q-value'])))
    print('\\n',label, 'hits', len(rows))
    print('family\\thits\\tq<0.05\\tmin_q')
    for f,alts in fam.items():
        vals=[(p,q) for alt,p,q in rows if alt in alts]
        print(f'{f}\\t{len(vals)}\\t{sum(q<0.05 for p,q in vals)}\\t{min((q for p,q in vals), default=float(\"nan\")):.3g}')
PY"
